-- LerneDeutsch · Quiz interactivo A1.1
-- Pegar completo en Supabase → SQL Editor.
-- Contiene ejercicios estructurados para drag & drop, emparejar y escuchar números.
-- Idempotente: se puede volver a ejecutar y actualiza el contenido por slug.

create table if not exists public.quiz_questions (
  id          bigint generated by default as identity primary key,
  slug        text not null unique,
  level       text not null default 'A1.1',
  topic       text not null,
  order_idx   integer not null,
  interaction text not null check (interaction in ('drag_drop','match','listen_choose','listen_match')),
  prompt      text not null,
  data        jsonb not null,
  explanation text not null,
  created_at  timestamptz not null default now()
);

create index if not exists quiz_questions_level_topic_idx
  on public.quiz_questions (level, topic, order_idx);

alter table public.quiz_questions enable row level security;
grant select on public.quiz_questions to authenticated;
revoke all on public.quiz_questions from anon, authenticated;
grant select on public.quiz_questions to authenticated;

drop policy if exists "quiz questions: lectura autenticada" on public.quiz_questions;
create policy "quiz questions: lectura autenticada"
  on public.quiz_questions for select to authenticated using (true);

-- Historial privado: cada intento se conserva; no se sobrescriben resultados anteriores.
create table if not exists public.quiz_attempts (
  id              bigint generated by default as identity primary key,
  user_id         uuid not null default auth.uid() references auth.users(id) on delete cascade,
  quiz_key        text not null default 'final-a1.1' check (quiz_key = 'final-a1.1'),
  score           integer not null check (score >= 0),
  total_questions integer not null check (total_questions > 0),
  percentage      numeric(5,2) generated always as (round(score::numeric * 100 / total_questions, 2)) stored,
  answers         jsonb not null default '[]'::jsonb,
  finished_at     timestamptz not null default now(),
  check (score <= total_questions)
);

create index if not exists quiz_attempts_user_best_idx
  on public.quiz_attempts (user_id, quiz_key, percentage desc, finished_at desc);

alter table public.quiz_attempts enable row level security;
revoke all on public.quiz_attempts from anon, authenticated;
grant select, insert on public.quiz_attempts to authenticated;
grant usage, select on sequence public.quiz_attempts_id_seq to authenticated;

drop policy if exists "quiz attempts: leer propios" on public.quiz_attempts;
create policy "quiz attempts: leer propios"
  on public.quiz_attempts for select to authenticated
  using ((select auth.uid()) = user_id);

drop policy if exists "quiz attempts: crear propios" on public.quiz_attempts;
create policy "quiz attempts: crear propios"
  on public.quiz_attempts for insert to authenticated
  with check ((select auth.uid()) = user_id);

-- Preferencias individuales para la invitación del final.
create table if not exists public.quiz_user_preferences (
  user_id          uuid primary key default auth.uid() references auth.users(id) on delete cascade,
  hide_final_invite boolean not null default false,
  updated_at       timestamptz not null default now()
);

alter table public.quiz_user_preferences enable row level security;
revoke all on public.quiz_user_preferences from anon, authenticated;
grant select, insert, update on public.quiz_user_preferences to authenticated;

drop policy if exists "quiz preferences: leer propias" on public.quiz_user_preferences;
create policy "quiz preferences: leer propias"
  on public.quiz_user_preferences for select to authenticated
  using ((select auth.uid()) = user_id);

drop policy if exists "quiz preferences: crear propias" on public.quiz_user_preferences;
create policy "quiz preferences: crear propias"
  on public.quiz_user_preferences for insert to authenticated
  with check ((select auth.uid()) = user_id);

drop policy if exists "quiz preferences: actualizar propias" on public.quiz_user_preferences;
create policy "quiz preferences: actualizar propias"
  on public.quiz_user_preferences for update to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

insert into public.quiz_questions (slug, level, topic, order_idx, interaction, prompt, data, explanation)
values
('presentacion-orden-01','A1.1','presentacion',1,'drag_drop','Ordena la presentación: «Me llamo Ana y tengo 20 años».', $j${"tokens":["Ich","heiße","Ana","und","bin","zwanzig","Jahre","alt."],"answer":["Ich","heiße","Ana","und","bin","zwanzig","Jahre","alt."],"note":"Arrastra las palabras para formar la frase."}$j$::jsonb,'Ich heiße Ana und bin zwanzig Jahre alt. Para la edad se usa «sein»: ich bin … Jahre alt.'),
('presentacion-ich-komme-01','A1.1','presentacion',2,'drag_drop','Completa: «Ich ___ aus Kolumbien.» (Vengo de Colombia).', $j${"tokens":["komme","kommt","wohne"],"answer":"komme","sentence":"Ich ___ aus Kolumbien."}$j$::jsonb,'«Ich komme aus …» expresa el lugar de origen.'),
('presentacion-beruf-01','A1.1','presentacion',3,'drag_drop','Completa: «Ich ___ Studentin.» (Soy estudiante).', $j${"tokens":["bin","heiße","komme"],"answer":"bin","sentence":"Ich ___ Studentin."}$j$::jsonb,'El verbo sein en primera persona es «ich bin». Los sustantivos de profesiones se escriben con mayúscula.'),
('presentacion-woher-01','A1.1','presentacion',4,'match','Empareja cada pregunta con la respuesta adecuada.', $j${"pairs":[{"left":"Wie heißt du?","right":"Ich heiße Luis."},{"left":"Wie alt bist du?","right":"Ich bin 19 Jahre alt."},{"left":"Was machst du beruflich?","right":"Ich bin Lehrer."},{"left":"Woher kommst du?","right":"Ich komme aus Peru."}]}$j$::jsonb,'Wie heißt du? pregunta el nombre; Wie alt bist du? la edad; Was machst du beruflich? la ocupación; Woher kommst du? el origen.'),
('presentacion-verbos-01','A1.1','presentacion',5,'drag_drop','Ordena: «¿De dónde eres?»', $j${"tokens":["kommst","du","Woher","?"],"answer":["Woher","kommst","du","?"],"note":"Recuerda: el verbo va en segunda posición."}$j$::jsonb,'La pregunta se forma con interrogativo + verbo + sujeto: Woher kommst du?'),
('familia-vocab-01','A1.1','familia',1,'match','Une los miembros de la familia con su significado.', $j${"pairs":[{"left":"der Vater","right":"el padre"},{"left":"die Mutter","right":"la madre"},{"left":"der Bruder","right":"el hermano"},{"left":"die Schwester","right":"la hermana"},{"left":"die Eltern","right":"los padres"}]}$j$::jsonb,'Aprende cada sustantivo junto con su artículo; Eltern es plural.'),
('familia-vocab-02','A1.1','familia',2,'match','Empareja más familiares.', $j${"pairs":[{"left":"der Onkel","right":"el tío"},{"left":"die Tante","right":"la tía"},{"left":"das Kind","right":"el niño / la niña"},{"left":"die Kinder","right":"los niños / hijos"},{"left":"der Sohn","right":"el hijo"},{"left":"die Tochter","right":"la hija"}]}$j$::jsonb,'Sohn es hijo, Tochter es hija y Kinder es el plural de Kind.'),
('familia-articulos-01','A1.1','familia',3,'drag_drop','Arrastra el artículo correcto a cada familiar.', $j${"items":["Vater","Mutter","Kind","Bruder","Schwester"],"targets":["der","die","das"],"answer":{"Vater":"der","Mutter":"die","Kind":"das","Bruder":"der","Schwester":"die"}}$j$::jsonb,'Vater y Bruder son masculinos; Mutter y Schwester femeninos; Kind es neutro.'),
('familia-presentar-01','A1.1','familia',4,'drag_drop','Completa: «Das ist ___ Mutter. Sie heißt Elena.» (Esta es mi madre).', $j${"tokens":["meine","mein","meinen"],"answer":"meine","sentence":"Das ist ___ Mutter."}$j$::jsonb,'Mutter es femenino: el posesivo mein recibe la terminación -e: meine Mutter.'),
('familia-posesivo-01','A1.1','familia',5,'drag_drop','Completa: «Das ist ___ Vater. Er heißt Carlos.» (Este es mi padre).', $j${"tokens":["mein","meine","meinen"],"answer":"mein","sentence":"Das ist ___ Vater."}$j$::jsonb,'Vater es masculino y aquí está en nominativo: mein Vater.'),
('gram-nominativo-01','A1.1','gramatica',1,'drag_drop','Pon cada sustantivo en el grupo nominativo correcto.', $j${"items":["Mann","Frau","Kind"],"targets":["der","die","das"],"answer":{"Mann":"der","Frau":"die","Kind":"das"}}$j$::jsonb,'El nominativo suele marcar al sujeto: der Mann, die Frau, das Kind.'),
('gram-nominativo-02','A1.1','gramatica',2,'drag_drop','Selecciona los artículos nominativos para completar las frases.', $j${"sentences":[{"text":"___ Mann kommt aus Berlin.","answer":"Der"},{"text":"___ Frau arbeitet heute.","answer":"Die"},{"text":"___ Kind spielt.","answer":"Das"}],"tokens":["Der","Die","Das"]}$j$::jsonb,'El sujeto está en nominativo: der Mann, die Frau, das Kind.'),
('gram-acusativo-01','A1.1','gramatica',3,'drag_drop','Cambia el artículo al acusativo: «Ich sehe ___ Mann.»', $j${"tokens":["den","dem","der"],"answer":"den","sentence":"Ich sehe ___ Mann."}$j$::jsonb,'El objeto directo va en acusativo. El artículo masculino cambia de der a den.'),
('gram-acusativo-02','A1.1','gramatica',4,'drag_drop','Completa con el artículo acusativo: «Ich kaufe ___ Apfel.»', $j${"tokens":["einen","ein","eine"],"answer":"einen","sentence":"Ich kaufe ___ Apfel."}$j$::jsonb,'Apfel es masculino. En acusativo, ein se declina como einen.'),
('gram-acusativo-03','A1.1','gramatica',5,'drag_drop','Completa: «Wir kaufen ___ Banane und ___ Brot.»', $j${"tokens":["eine","ein","einen"],"answers":["eine","ein"],"sentences":["Wir kaufen ___ Banane","und ___ Brot"]}$j$::jsonb,'Banane es femenino: eine Banane. Brot es neutro y no cambia en acusativo: ein Brot.'),
('gram-caso-01','A1.1','gramatica',6,'match','Identifica si el sustantivo resaltado funciona como sujeto (nominativo) u objeto directo (acusativo).', $j${"pairs":[{"left":"Der Mann kauft Brot. → Der Mann","right":"Nominativo (sujeto)"},{"left":"Ich sehe den Mann. → den Mann","right":"Acusativo (objeto directo)"},{"left":"Die Frau trinkt Wasser. → Die Frau","right":"Nominativo (sujeto)"},{"left":"Er isst einen Apfel. → einen Apfel","right":"Acusativo (objeto directo)"}]}$j$::jsonb,'El sujeto realiza la acción y va en nominativo; el objeto directo la recibe y va en acusativo.'),
('super-frutas-01','A1.1','supermercado',1,'match','Empareja frutas con sus nombres en alemán y su artículo.', $j${"pairs":[{"left":"der Apfel","right":"la manzana"},{"left":"die Banane","right":"el plátano"},{"left":"die Orange","right":"la naranja"},{"left":"die Erdbeere","right":"la fresa"},{"left":"die Birne","right":"la pera"},{"left":"die Traube","right":"la uva"}]}$j$::jsonb,'Memoriza las frutas con artículo: der Apfel, pero die Banane, die Orange, die Erdbeere, die Birne, die Traube.'),
('super-verduras-01','A1.1','supermercado',2,'match','Empareja verduras con su significado.', $j${"pairs":[{"left":"die Tomate","right":"el tomate"},{"left":"die Kartoffel","right":"la papa / patata"},{"left":"die Karotte","right":"la zanahoria"},{"left":"die Zwiebel","right":"la cebolla"},{"left":"die Gurke","right":"el pepino"},{"left":"der Salat","right":"la lechuga / ensalada"}]}$j$::jsonb,'La mayoría de estos nombres son femeninos. Salat es masculino: der Salat.'),
('super-plurales-01','A1.1','supermercado',3,'match','Empareja singular y plural.', $j${"pairs":[{"left":"der Apfel","right":"die Äpfel"},{"left":"die Banane","right":"die Bananen"},{"left":"die Tomate","right":"die Tomaten"},{"left":"die Kartoffel","right":"die Kartoffeln"},{"left":"das Brot","right":"die Brote"},{"left":"das Ei","right":"die Eier"}]}$j$::jsonb,'Los plurales varían: Umlaut, -e, -en o -er. En plural, el artículo definido es die.'),
('super-articulos-01','A1.1','supermercado',4,'drag_drop','Clasifica los productos por su artículo definido.', $j${"items":["Käse","Milch","Brot","Wasser","Tomate","Apfel"],"targets":["der","die","das"],"answer":{"Käse":"der","Milch":"die","Brot":"das","Wasser":"das","Tomate":"die","Apfel":"der"}}$j$::jsonb,'der Käse, die Milch, das Brot, das Wasser, die Tomate, der Apfel.'),
('super-verbos-frecuencia-01','A1.1','supermercado',5,'match','Empareja los adverbios de frecuencia.', $j${"pairs":[{"left":"immer","right":"siempre"},{"left":"oft","right":"a menudo"},{"left":"manchmal","right":"a veces"},{"left":"selten","right":"rara vez"},{"left":"nie","right":"nunca"}]}$j$::jsonb,'Estos adverbios describen con qué frecuencia haces algo.'),
('super-frecuencia-orden-01','A1.1','supermercado',6,'drag_drop','Ordena: «A menudo compro manzanas en el supermercado».', $j${"tokens":["kaufe","Supermarkt","Ich","oft","im","Äpfel"],"answer":["Ich","kaufe","oft","Äpfel","im","Supermarkt."],"note":"La forma Äpfel ya está en plural."}$j$::jsonb,'La oración principal alemana coloca el verbo conjugado en la segunda posición: Ich kaufe oft Äpfel im Supermarkt.'),
('restaurante-pedir-01','A1.1','restaurante',1,'match','Empareja las frases útiles en un restaurante.', $j${"pairs":[{"left":"Ich möchte eine Suppe, bitte.","right":"Quisiera una sopa, por favor."},{"left":"Die Speisekarte, bitte.","right":"La carta, por favor."},{"left":"Was empfehlen Sie?","right":"¿Qué recomienda?"},{"left":"Die Rechnung, bitte.","right":"La cuenta, por favor."},{"left":"Ich hätte gern Wasser.","right":"Quisiera agua."}]}$j$::jsonb,'«Ich möchte …» y «Ich hätte gern …» son formas corteses para pedir.'),
('restaurante-comida-01','A1.1','restaurante',2,'match','Une cada plato con su traducción.', $j${"pairs":[{"left":"die Suppe","right":"la sopa"},{"left":"der Salat","right":"la ensalada"},{"left":"das Hähnchen","right":"el pollo"},{"left":"der Fisch","right":"el pescado"},{"left":"die Kartoffeln","right":"las papas"},{"left":"das Wasser","right":"el agua"}]}$j$::jsonb,'Suppe es femenino, Salat masculino, Hähnchen y Wasser neutros.'),
('restaurante-pedido-02','A1.1','restaurante',3,'drag_drop','Ordena el pedido: «Quisiera un café, por favor».', $j${"tokens":["bitte","möchte","Kaffee,","Ich","einen"],"answer":["Ich","möchte","einen","Kaffee,","bitte."],"note":"Kaffee es masculino; después de möchten va en acusativo."}$j$::jsonb,'Kaffee es masculino: der Kaffee. Como objeto directo: einen Kaffee.'),
('casa-habitaciones-01','A1.1','casa',1,'match','Empareja las partes de la casa con su significado.', $j${"pairs":[{"left":"das Zimmer","right":"la habitación"},{"left":"die Küche","right":"la cocina"},{"left":"das Schlafzimmer","right":"el dormitorio"},{"left":"das Badezimmer","right":"el baño"},{"left":"das Wohnzimmer","right":"la sala"},{"left":"der Garten","right":"el jardín"}]}$j$::jsonb,'Fíjate en los artículos: Zimmer, Schlafzimmer, Badezimmer y Wohnzimmer son neutros.'),
('casa-objetos-01','A1.1','casa',2,'match','Empareja objetos de la casa.', $j${"pairs":[{"left":"der Tisch","right":"la mesa"},{"left":"der Stuhl","right":"la silla"},{"left":"das Bett","right":"la cama"},{"left":"die Tür","right":"la puerta"},{"left":"das Fenster","right":"la ventana"},{"left":"die Lampe","right":"la lámpara"}]}$j$::jsonb,'Aprende el artículo junto con cada palabra para reconocer el género gramatical.'),
('casa-clasificar-01','A1.1','casa',3,'drag_drop','Coloca cada objeto en la habitación más lógica.', $j${"items":["der Herd","das Bett","die Dusche","der Kühlschrank","das Sofa"],"targets":["die Küche","das Schlafzimmer","das Badezimmer","das Wohnzimmer"],"answer":{"der Herd":"die Küche","der Kühlschrank":"die Küche","das Bett":"das Schlafzimmer","die Dusche":"das Badezimmer","das Sofa":"das Wohnzimmer"}}$j$::jsonb,'Herd y Kühlschrank suelen estar en la cocina; Bett en el dormitorio; Dusche en el baño; Sofa en la sala.'),
('casa-frase-01','A1.1','casa',4,'drag_drop','Completa: «Das Buch ist ___ Tisch.» (El libro está sobre la mesa).', $j${"tokens":["auf dem","auf den","auf der"],"answer":"auf dem","sentence":"Das Buch ist ___ Tisch."}$j$::jsonb,'La pregunta Wo? (¿dónde?) indica ubicación. Tisch es masculino y con auf + dativo queda auf dem Tisch.'),
('numeros-hören-01','A1.1','numeros',1,'listen_choose','Escucha y marca el número que oyes.', $j${"audio_text":"sieben","tts":"/api/tts?word=sieben","choices":[7,17,70],"answer":7,"speak_language":"de-DE"}$j$::jsonb,'sieben = 7. Escucha la vocal larga y diferencia sieben de siebzehn (17) y siebzig (70).'),
('numeros-hören-02','A1.1','numeros',2,'listen_choose','Escucha y marca el número que oyes.', $j${"audio_text":"vierzehn","tts":"/api/tts?word=vierzehn","choices":[4,14,40],"answer":14,"speak_language":"de-DE"}$j$::jsonb,'vierzehn = 14; vierzig = 40.'),
('numeros-hören-03','A1.1','numeros',3,'listen_choose','Escucha y marca el número que oyes.', $j${"audio_text":"fünfzehn","tts":"/api/tts?word=f%C3%BCnfzehn","choices":[5,15,50],"answer":15,"speak_language":"de-DE"}$j$::jsonb,'fünfzehn = 15; fünfzig = 50.'),
('numeros-hören-04','A1.1','numeros',4,'listen_choose','Escucha y marca el número que oyes.', $j${"audio_text":"achtundzwanzig","tts":"/api/tts?word=achtundzwanzig","choices":[18,28,82],"answer":28,"speak_language":"de-DE"}$j$::jsonb,'En alemán se dice primero la unidad: acht-und-zwanzig = 28.'),
('numeros-hören-05','A1.1','numeros',5,'listen_choose','Escucha y marca el número que oyes.', $j${"audio_text":"dreiundvierzig","tts":"/api/tts?word=dreiundvierzig","choices":[34,43,53],"answer":43,"speak_language":"de-DE"}$j$::jsonb,'drei-und-vierzig = 3 + 40 = 43.'),
('numeros-emparejar-01','A1.1','numeros',6,'listen_match','Escucha cada número y empareja el audio con la cifra.', $j${"items":[{"audio_text":"zwölf","tts":"/api/tts?word=zw%C3%B6lf","answer":"12"},{"audio_text":"sechzehn","tts":"/api/tts?word=sechzehn","answer":"16"},{"audio_text":"dreißig","tts":"/api/tts?word=drei%C3%9Fig","answer":"30"},{"audio_text":"fünfundzwanzig","tts":"/api/tts?word=f%C3%BCnfundzwanzig","answer":"25"}],"targets":["12","16","25","30"],"speak_language":"de-DE"}$j$::jsonb,'Practica distinguir las decenas y recordar que las unidades preceden a und en números como fünfundzwanzig.'),
('numeros-emparejar-02','A1.1','numeros',7,'listen_match','Escucha y empareja cada audio con su cifra.', $j${"items":[{"audio_text":"einundzwanzig","tts":"/api/tts?word=einundzwanzig","answer":"21"},{"audio_text":"zweiunddreißig","tts":"/api/tts?word=zweiunddrei%C3%9Fig","answer":"32"},{"audio_text":"siebenundvierzig","tts":"/api/tts?word=siebenundvierzig","answer":"47"},{"audio_text":"neunundneunzig","tts":"/api/tts?word=neunundneunzig","answer":"99"}],"targets":["21","32","47","99"],"speak_language":"de-DE"}$j$::jsonb,'Para 21–99 (salvo decenas exactas) se dice unidad + und + decena.'),
('numeros-hören-06','A1.1','numeros',8,'listen_choose','Escucha y marca la cifra correcta.', $j${"audio_text":"hundertdrei","tts":"/api/tts?word=hundertdrei","choices":[103,130,300],"answer":103,"speak_language":"de-DE"}$j$::jsonb,'hundertdrei significa cien tres, es decir, 103.'),
('numeros-hören-07','A1.1','numeros',9,'listen_choose','Escucha y marca la cifra correcta.', $j${"audio_text":"zweihundertfünfzig","tts":"/api/tts?word=zweihundertf%C3%BCnfzig","choices":[205,250,520],"answer":250,"speak_language":"de-DE"}$j$::jsonb,'zweihundertfünfzig = doscientos cincuenta (250).'),
('numeros-orden-01','A1.1','numeros',10,'drag_drop','Ordena las partes para formar el número 34 en alemán.', $j${"tokens":["vierzig","drei","und"],"answer":["drei","und","vierzig"],"result":"vierunddreißig","note":"La unidad se dice antes de la decena."}$j$::jsonb,'34 se dice vier-und-dreißig: primero cuatro y luego treinta.'),
('repaso-mixto-01','A1.1','repaso',1,'match','Repaso: relaciona la frase con su función.', $j${"pairs":[{"left":"Ich bin 22 Jahre alt.","right":"decir la edad"},{"left":"Ich komme aus Chile.","right":"decir el origen"},{"left":"Das ist meine Schwester.","right":"presentar a una familiar"},{"left":"Ich kaufe einen Apfel.","right":"acusativo masculino"},{"left":"Die Küche ist groß.","right":"describir una habitación"}]}$j$::jsonb,'Repasa edad, procedencia, familia, acusativo y vocabulario de la casa.')
on conflict (slug) do update set
  level = excluded.level,
  topic = excluded.topic,
  order_idx = excluded.order_idx,
  interaction = excluded.interaction,
  prompt = excluded.prompt,
  data = excluded.data,
  explanation = excluded.explanation;

-- Comprobación rápida del contenido cargado
select topic, count(*) as ejercicios
from public.quiz_questions
where level = 'A1.1'
group by topic
order by min(order_idx), topic;
